// ProntoPraIA - Auditoria robusta
const results = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const url = j.url || j.URL || 'URL desconhecida';
  const resp = j.data || {};
  const statusCode = resp.statusCode || j.statusCode || null;
  const raw = resp.body !== undefined ? resp.body : (j.html ?? j.body ?? '');
  const html = typeof raw === 'string' ? raw : (raw ? JSON.stringify(raw) : '');
  const erroHttp = (statusCode && statusCode >= 400) ? String(statusCode) : (j.error || item.error || null);
  let nota = 0;
  const faltando = [];
  const headMatch = html.match(/<head[^>]*>([\s\S]*?)<\/head>/i);
  const headHtml = headMatch ? headMatch[1] : html;
  const hasTitle = /<title[^>]*>[\s\S]+?<\/title>/i.test(headHtml);
  if (hasTitle) { nota += 25; } else { faltando.push('title'); }
  const hasOgImage = /<meta[^>]+property=["']og:image["'][^>]*>/i.test(html);
  if (hasOgImage) { nota += 25; } else { faltando.push('og:image'); }
  const hasOgPrice = /<meta[^>]+property=["']og:price:amount["'][^>]*>/i.test(html);
  if (hasOgPrice) { nota += 25; } else { faltando.push('og:price:amount'); }
  const hasJsonLd = /<script[^>]+type=["']application\/ld\+json["'][^>]*>/i.test(html);
  if (hasJsonLd) { nota += 25; } else { faltando.push('json-ld'); }
  if (nota > 100) nota = 100;
  let status = 'Crítico';
  if (nota >= 75) status = 'Pronto';
  else if (nota >= 50) status = 'Básico';
  if (!html || html.trim() === '') {
    nota = 0; status = 'Crítico';
    if (erroHttp) faltando.push('erro-http: ' + String(erroHttp).substring(0, 80));
    else if (!faltando.includes('html-vazio')) faltando.push('html-vazio (bloqueio/timeout?)');
  } else if (erroHttp) {
    faltando.push('erro-http: ' + String(erroHttp).substring(0, 80));
  }
  let prodName = 'Produto exemplo';
  let prodImage = 'https://exemplo.com/imagem.jpg';
  const mTitle = headHtml.match(/<title[^>]*>([^<]+)<\/title>/i);
  if (mTitle && mTitle[1]) prodName = mTitle[1].trim().substring(0, 150);
  const mImg = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i);
  if (mImg && mImg[1]) prodImage = mImg[1];
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    'name': prodName,
    'image': prodImage,
    'description': 'Descricao do produto em ' + url,
    'brand': { '@type': 'Brand', 'name': 'Marca do produto' },
    'offers': { '@type': 'Offer', 'url': url, 'priceCurrency': 'BRL', 'price': '0.00', 'availability': 'https://schema.org/InStock' }
  };
  results.push({ json: { url, nota, status, faltando: faltando.join(', '), json_ld_sugerido: JSON.stringify(jsonLd) } });
}
return results;

// ProntoPraIA - Salvar CSV com caminho absoluto
const fs = require('fs');
const filePath = 'C:\\Users\\User\\Desktop\\prontopraia\\resultados_auditoria.csv';

function csvEscape(v) {
  let s = String(v ?? '');
  if (/^[=+\-@]/.test(s)) s = "'" + s;
  if (/["\n,]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

const header = 'url,nota,status,faltando,json_ld_sugerido\n';
if (!fs.existsSync(filePath)) {
  fs.writeFileSync(filePath, header);
}

const items = $input.all();
const lines = items.map(item => {
  const j = item.json || {};
  return [j.url, j.nota, j.status, j.faltando, j.json_ld_sugerido].map(csvEscape).join(',');
}).join('\n') + '\n';

fs.appendFileSync(filePath, lines);
return items;

